using FluentAssertions; using Sigov.Domain.Agro; using Sigov.Domain.Agro.Enums; using Xunit;
namespace Sigov.UnitTests.Agro; public sealed class AgroCompraAgriculturaFamiliarRulesTests{[Fact] public void Compra_af_exige_produtor()=>FluentActions.Invoking(()=>new CompraAgriculturaFamiliar(1,1,2026,0,"Produto",1,"KG",10,AgroCompraAgriculturaFamiliarStatus.REGISTRADA)).Should().Throw<ArgumentException>(); [Fact] public void Compra_af_exige_produto()=>FluentActions.Invoking(()=>new CompraAgriculturaFamiliar(1,1,2026,1,"",1,"KG",10,AgroCompraAgriculturaFamiliarStatus.REGISTRADA)).Should().Throw<ArgumentException>(); [Fact] public void Quantidade_deve_ser_maior_que_zero()=>FluentActions.Invoking(()=>new CompraAgriculturaFamiliar(1,1,2026,1,"Produto",0,"KG",10,AgroCompraAgriculturaFamiliarStatus.REGISTRADA)).Should().Throw<ArgumentException>(); [Fact] public void Valor_total_e_calculado_corretamente(){var c=new CompraAgriculturaFamiliar(1,1,2026,1,"Produto",2,"KG",10,AgroCompraAgriculturaFamiliarStatus.REGISTRADA); c.ValorTotal.Should().Be(20);}}
